window.REPORT_PRELOAD_CACHE["AT&T.html"] = {"version":"b34ab32cb37f05ae4fc271f1b046e76dbb025bd636344eef305352b6d7a24d6e","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>美国电话电报公司 AT&T Inc. (NYSE: T) 深度研究报告：纯粹电信运营商转型、5G与光纤双核驱动、高自由现金流与稳健高息防御堡垒</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#030712',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n attblue: {\n 300: '#93C5FD',\n 400: '#60A5FA',\n 500: '#3B82F6',\n 600: '#2563EB',\n 700: '#1D4ED8',\n },\n emerald: {\n 400: '#34D399',\n 500: '#10B981',\n 600: '#059669',\n },\n teal: {\n 400: '#22D3EE',\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n /* 自定义滚动条 */\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n /* 打印友好优化 */\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n /* 卡片悬浮微光与上移过渡 */\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n /* 侧边导航激活态 */\n .nav-link.active {\n background: linear-gradient(90deg, rgba(37, 99, 235, 0.24) 0%, rgba(16, 185, 129, 0.06) 100%);\n border-left: 3px solid #2563EB;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-attblue-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部全局阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-attblue-600 via-attblue-400 to-emerald-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-attblue-400 to-attblue-600 flex items-center justify-center font-extrabold text-white text-xs shadow\">\n T\n </div>\n <div>\n <div class=\"text-[11px] text-attblue-400 font-semibold tracking-wider uppercase\">NYSE: T · Telecom Leader</div>\n <div class=\"text-sm font-bold leading-tight\">AT&T 美国电讯 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">AT&T 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务架构与5G/光纤双核</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重电信护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 全球电信巨头横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康、去杠杆与自由现金流推演</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球电信与高息红利资产研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (Q3 26 / FY26E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 (宽 280px) -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <!-- 机构品牌头 -->\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-attblue-400 via-attblue-500 to-attblue-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-attblue-500/25\">\n T\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-attblue-400 bg-attblue-500/15 px-2 py-0.5 rounded\">NYSE: T</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">AT&T 深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 美国电信巨头 · 5G移动通信与光纤宽带基础设施霸主、高自由现金流现金奶牛\n </p>\n </div>\n\n <!-- 股票实时快照徽章 -->\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">参考股价 (52周区间)</span>\n <span class=\"font-mono font-bold text-white\">~$23.45 <span class=\"text-slate-400 text-[10px]\">($16.2-$24.8)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">2026E 自由现金流 (FCF)</span>\n <span class=\"font-mono font-bold text-emerald-400\">~$16.5B–$17.5B</span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值与股息率</span>\n <span class=\"font-mono font-bold text-attblue-400\">~9.5x P/E · 股息率 4.75%</span>\n </div>\n </div>\n\n <!-- 七大核心章节目录导航 -->\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-attblue-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务架构与5G/光纤双核</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重电信护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>全球电信巨头横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康、去杠杆与现金流推演</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <!-- 侧边栏底部工具栏 -->\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition cursor-pointer\">\n <svg class=\"w-3.5 h-3.5 text-attblue-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-attblue-500 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-gradient-to-r from-attblue-500 to-attblue-600 hover:from-attblue-600 hover:to-attblue-700 text-white text-xs font-extrabold transition shadow-sm cursor-pointer\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- =========================================================\n 00. Hero 研报封面区与执行摘要\n ========================================================= -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-attblue-500/15 text-attblue-600 dark:text-attblue-400 font-bold border border-attblue-500/30\">评级：买入 / 纯粹电信转型兑现、自由现金流与高息防御底仓</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：2026Q3  postpaid 手机净增稳健、光纤宽带加速渗透期</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NYSE: T</span>\n </div>\n </div>\n\n <!-- Hero 标题卡片 -->\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#60A5FA 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-attblue-500/20 border border-attblue-400/40 text-attblue-300 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-attblue-400 animate-pulse\"></span>\n <span>CORE THESIS · 剥离媒体业务后纯粹电信化 × 5G后付费用户稳健黏性 × 光纤宽带（AT&T Fiber）高速渗透 × 165亿+美元自由现金流机器</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 美国电话电报公司 AT&T Inc. (NYSE: T) 深度研究报告：纯粹电信巨头战略兑现、5G与千兆光纤双核护城河、债务压降与高自由现金流防御堡垒\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 在成功剥离非核心媒体资产（WarnerMedia）回归纯粹电信运营商后，AT&T 在 CEO <strong class=\"text-white\">John Stankey</strong> 的带领下交出高质量的 2026Q3 答卷：得益于美国消费者对 5G 高端套餐的强劲需求与 <strong class=\"text-attblue-300\">AT&T Fiber 千兆光纤</strong>的持续高速渗透（Q3 光纤宽带净增保持行业领先），公司 postpaid 手机流失率维持在美股三大运营商最低水平。全年自由现金流（FCF）指引锁定在稳健的 <strong class=\"text-emerald-400\">~$165–$175亿</strong>，净债务杠杆率持续下降至中长期的 <strong class=\"text-white\">~2.5x</strong> 目标位，构筑起美股不可多得的高分红、低波动防御性现金牛。\n </p>\n\n <!-- 核心投资结论高亮条 -->\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">5G 与光纤双轮高质量增长</div>\n <div class=\"text-white font-semibold\">Postpaid 手机用户增长稳健，流失率行业最低；Fiber 光纤家庭覆盖与 ARPU 双双攀升</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">超 165 亿美元自由现金流</div>\n <div class=\"text-attblue-300 font-semibold\">资本开支高峰期已过，FCF 强劲回血，完全覆盖安全稳健的 4.75%+ 股息分红</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">去杠杆与资产负债表修复</div>\n <div class=\"text-emerald-400 font-semibold\">净债务持续压降，信用评级稳固，估值处于历史中枢偏低配置区间</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4个核心 KPI 卡片 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <!-- KPI 1 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>总市值与最新股价</span>\n <span class=\"p-1.5 rounded-lg bg-attblue-500/15 text-attblue-600 dark:text-attblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$168.5B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">~$23.45</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 随着纯电信战略落地与自由现金流恢复，估值稳步回升，吸引大机构长线红利配置。\n </p>\n </div>\n\n <!-- KPI 2 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>2026E 自由现金流 (FCF)</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-2xl sm:text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$16.5B–$17.5B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/15 px-2 py-0.5 rounded\">现金流强劲</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 26Q3 单季 FCF 表现超预期，全年指引坚实，完全覆盖每年约 $8B 的派息需求。\n </p>\n </div>\n\n <!-- KPI 3 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>净债务杠杆率 (Net Debt / EBITDA)</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~2.5x</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/15 px-2 py-0.5 rounded\">目标稳步达成</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 集团稳步推进资产负债表修复，杠杆率已回落至管理层中长期目标区间（2.5x 左右）。\n </p>\n </div>\n\n <!-- KPI 4 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>远期股息率与派息安全垫</span>\n <span class=\"p-1.5 rounded-lg bg-attblue-500/15 text-attblue-600 dark:text-attblue-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">4.75%</span>\n <span class=\"text-xs font-bold text-attblue-700 dark:text-attblue-400 bg-attblue-500/15 px-2 py-0.5 rounded\">派息率 ~50%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 当前年化每股派息 $1.11，股息支付率仅占自由现金流的约 50%，具备极高安全垫与可持续性。\n </p>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 一、 业务与收入架构 (Business & Revenue Architecture)\n ========================================================= -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-attblue-600 dark:text-attblue-400\">Section 01 · Business & Revenue Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与收入架构：移动通信与光纤宽带双核齐驱，无线服务收入稳步高增</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY26E 总营收 ~$122B+ · 移动与宽带主业占比 &gt;90%</span>\n </div>\n\n <!-- 交互式 Chart.js 双视图切换面板 -->\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <!-- 左侧：双视图图表 -->\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">2023–2026E 营业收入与自由现金流（FCF）演进</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">剥离媒体后核心电信营收企稳于 ~$122B，资本开支回落驱动 FCF 强劲回升至 $17B 平台</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('rev_fcf')\" id=\"btn-chart-rev\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-attblue-600 dark:text-attblue-400 shadow-sm transition cursor-pointer\">视图A：营收与自由现金流</button>\n <button onclick=\"switchBizChart('sub_split')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer\">视图B：2026Q3 核心用户与光纤渗透</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"attBizChart\"></canvas>\n </div>\n </div>\n\n <!-- 右侧：结构性拆解核心洞察 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">2026Q3 核心经营三大突破引擎</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-attblue-500/15 text-attblue-600 dark:text-attblue-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">Postpaid 手机用户高质量净增与行业最低流失率</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n Q3 录得稳健的 postpaid 手机用户净增量，同时客户流失率（Churn Rate）持续保持全美三大运营商最优水平，验证 5G 网络质量与套餐吸引力。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">AT&T Fiber 千兆光纤宽带渗透率加速扩张</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 光纤家庭覆盖数（Passing Homes）持续扩大，Q3 光纤宽带净增数保持强劲，宽带 ARPU（每用户平均收入）稳步上扬，驱动固网业务从传统铜线向高速光纤全面蜕变。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">资本开支峰值已过，自由现金流如期释放</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 随着 C-band 5G 核心网络建设资本开支的高峰期过去，资本开支（CapEx）步入常态化平稳期，直接推动全年 FCF 锚定在 $165–$175 亿美元的高位区间。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">纯电信运营商战略核心</span>\n <span class=\"font-bold text-attblue-600 dark:text-attblue-400\">聚焦连接主业、释放现金流</span>\n </div>\n </div>\n </div>\n\n <!-- 四大业务分部详细卡片矩阵 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-5\">\n <!-- 分部 1：Mobility 移动业务 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-attblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-attblue-500/15 text-attblue-700 dark:text-attblue-400 text-xs font-bold\">第一现金奶牛 · 占总营收 ~70%</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">无线服务收入稳健增长</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">1. 移动通信业务 (Mobility Services & Equipment)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 提供全美领先的 5G 无线 postpaid、prepaid 手机通信及物联网连接服务。凭借极具竞争力的“无缝以旧换新”与无限流量套餐，持续吸引高质量 postpaid 手机用户，无线服务收入（Wireless Service Revenue）保持高质量稳健增长。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>数千万 postpaid 核心用户基数</span>\n <span class=\"text-attblue-600 dark:text-attblue-400 font-semibold\">全美最低流失率基准</span>\n </div>\n </div>\n\n <!-- 分部 2：Business Wireline & Consumer Broadband -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-emerald-500/15 text-emerald-700 dark:text-emerald-400 text-xs font-bold\">高增长宽带引擎 · AT&T Fiber</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">千兆光纤 ARPU 提升</span>\n </div>\n <h3 class=\"text-lg font-bold text-slate-900 dark:text-white\">2. 消费与商业宽带业务 (Consumer & Business Wireline)</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 以 <strong>AT&T Fiber</strong> 千兆光纤为核心，通过不断扩展光纤家庭覆盖网（Passing Homes），实现宽带业务收入的强劲增长，有效对冲传统铜线业务（Legacy Wireline）的自然萎缩。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-[11px] font-mono text-slate-500 dark:text-slate-400\">\n <span>数百万光纤宽带付费家庭</span>\n <span class=\"text-emerald-600 dark:text-emerald-400 font-semibold\">光纤渗透率与ARPU双升</span>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 二、 行业地位与四重核心护城河 (Industry Position & Moat)\n ========================================================= -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：全国无线频谱、千兆光纤网络与庞大黏性用户</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">宽广护城河 (Wide Moat · 美国三大电信寡头之一)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧：四重护城河深度解析 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-attblue-500/15 text-attblue-600 dark:text-attblue-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">核心 5G 黄金频谱与无线基站网络</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n AT&T 拥有覆盖全美数亿人口的高品质 C-Band 及毫米波无线频谱资产，斥巨资打造的现代化 5G 网络确保了极高的网络吞吐量和极低的掉线率。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">AT&T Fiber 千兆光纤基础设施护城河</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 固网宽带资产历经数十年的铺设，构筑了难以复制的地下光纤网与基站回传光纤。千兆光纤直连家庭（FTTH）带来极高的客户粘性与行业最高的宽带 ARPU。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">极低流失率的高价值 Postpaid 用户群体</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 拥有全美庞大的优质后付费（Postpaid）手机用户群。由于家庭套餐和长期的信用捆绑，其手机流失率长期保持在极低水平，现金流收入极具周期抗性。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">$165亿+ 稳定自由现金流转化机器</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 电信业务具备极强的公用事业属性，在完成资本开支高峰期后，巨额营业现金流平稳转化为超 165 亿美元的自由现金流，派息安全垫坚如磐石。\n </p>\n </div>\n </div>\n\n <!-- 右侧：五维护城河雷达图 -->\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">美国三大电信巨头五维护城河雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">AT&T (T) vs Verizon (VZ) vs T-Mobile (TMUS)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 三、 全球电信巨头横向对比 (Competitive Landscape)\n ========================================================= -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-attblue-600 dark:text-attblue-400\">Section 03 · Global Telecom Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 全球电信巨头横向对比：AT&T、Verizon与T-Mobile的无线、光纤与估值交锋</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-attblue-500 text-white shadow-sm transition cursor-pointer\">全部电信巨头</button>\n <button onclick=\"filterCompetitors('us')\" data-filter=\"us\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">美国三大运营商</button>\n <button onclick=\"filterCompetitors('global')\" data-filter=\"global\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition cursor-pointer\">国际电信巨头参考</button>\n </div>\n </div>\n\n <!-- 横向对比矩阵表格 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">企业名称与代码</th>\n <th class=\"py-4 px-4 min-w-[130px]\">核心市场重心</th>\n <th class=\"py-4 px-4 min-w-[140px]\">网络与光纤优势</th>\n <th class=\"py-4 px-4 min-w-[100px]\">远期 P/E</th>\n <th class=\"py-4 px-4 min-w-[115px]\">股息率</th>\n <th class=\"py-4 px-4 min-w-[115px]\">营业利润率</th>\n <th class=\"py-4 px-5 min-w-[230px]\">核心优劣势与竞争定位评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <!-- 行 1：AT&T 基准 -->\n <tr data-category=\"us\" class=\"bg-attblue-500/5 dark:bg-attblue-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-attblue-500 text-white text-[10px] font-extrabold\">报告标的</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">AT&T (NYSE: T)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">5G Wireless + AT&T Fiber</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">全美无线与固网全覆盖</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-attblue-500/15 text-attblue-700 dark:text-attblue-400\">5G + 千兆光纤双核</span>\n </td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~9.5x</td>\n <td class=\"py-4 px-4 font-mono font-bold text-attblue-600 dark:text-attblue-400\">~4.75%</td>\n <td class=\"py-4 px-4 font-mono font-bold text-emerald-600 dark:text-emerald-400\">~22.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>纯电信高现金流防御堡垒：</strong>完成媒体剥离轻装上阵，FCF 超 $165亿，4.75% 股息率安全稳健，估值极具吸引力。\n </td>\n </tr>\n\n <!-- 行 2：Verizon VZ -->\n <tr data-category=\"us\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">Verizon (NYSE: VZ)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Fios + Wireless</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">美国本土无线与固网</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-semibold bg-teal-500/15 text-teal-700 dark:text-teal-400\">高端无线 + Fios光纤</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~9.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~6.10% (高股息)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~23.5%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300\">\n <strong>传统高股息对照：</strong>股息率略高于 AT&T，但无线用户增长势头近年来略逊于 AT&T 与 T-Mobile 的双向挤压。\n </td>\n </tr>\n\n <!-- 行 3：T-Mobile TMUS -->\n <tr data-category=\"us\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">T-Mobile (NASDAQ: TMUS)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">5G Un-carrier</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">全美高速扩张无线</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-emerald-500/15 text-emerald-700 dark:text-emerald-400\">中频5G网络领先</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~18.5x</td>\n <td class=\"py-4 px-4 font-mono text-slate-500 dark:text-slate-400\">~1.40% (偏成长)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~18.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300\">\n <strong>无线成长先锋：</strong>凭借中频 5G 优势在过去几年持续抢占 postpaid 手机市场份额，估值显著高于传统电信双雄。\n </td>\n </tr>\n\n <!-- 行 4：沃达丰 VOD -->\n <tr data-category=\"global\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">沃达丰 (LSE: VOD)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">欧洲与非洲跨国电信</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">欧洲及新兴市场</td>\n <td class=\"py-4 px-4\">\n <span class=\"inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-indigo-500/15 text-indigo-700 dark:text-indigo-400\">跨国移动与宽带</span>\n </td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~10.0x</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~5.50%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~15.0%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300\">\n <strong>欧洲电信转型参考：</strong>面临欧洲电信市场高度碎片化及价格战压力，正通过资产重组和剥离低效板块自救。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <!-- 配套 Chart.js 横向条形图：营业利润率与股息率对比 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要电信运营商营业利润率（Operating Margin）与远期股息率双维对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">AT&T 兼具 ~22% 的健康营业利润率与 ~4.75% 的高股息收益，在现金流安全与回报率之间实现完美平衡</p>\n </div>\n <span class=\"text-xs font-semibold text-attblue-700 dark:text-attblue-400 bg-attblue-500/15 px-2.5 py-1 rounded\">稳健 22% 营业利润率</span>\n </div>\n <div class=\"relative h-64 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 四、 财务健康与股息复利推演 (Financial Health & Dividend Simulator)\n ========================================================= -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 04 · Financial Health & Dividend Compounding Simulator</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康与现金流复利体系：$165亿+自由现金流与 DRIP 复利推演</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">资本开支常态化 · 自由现金流支撑极高股息安全垫</span>\n </div>\n\n <!-- 1. 财务健康度四大硬核指标卡 -->\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-attblue-600 dark:text-attblue-400 uppercase\">Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~22.0%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 纯电信业务运营效率不断优化，叠加传统高成本冗余剥离，核心营业利润率保持在稳健的高位。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Free Cash Flow (FCF)</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$17.0B</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 全年自由现金流稳定在 $165–$175 亿美元区间，为偿还债务和派发高额股息提供源源不断的现金造血。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Net Debt / EBITDA</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~2.5x</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 债务结构持续优化，评级机构对其次投资级（BBB+/Baa1）信用评级展望稳固。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-indigo-600 dark:text-indigo-400 uppercase\">Dividend Payout Ratio</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~50% FCF</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 每年约 $80 亿美元现金派息仅占 FCF 的一半，具备极强抗风险能力与股息防御属性。\n </p>\n </div>\n </div>\n\n <!-- 2. 交互式 Chart.js 自由现金流与资本开支趋势图 -->\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">2023–2026E 资本开支（CapEx）回落与自由现金流（FCF）强势回升趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">随着 5G 与光纤前期资本投入高峰过去，CapEx 稳定在 ~$19B 左右，推动 FCF 从低谷强势反弹至 ~$17B</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-attblue-700 dark:text-attblue-400 bg-attblue-500/15 px-2.5 py-1 rounded\">自由现金流稳居 $165亿+ 高地</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"fcfTrendChart\"></canvas>\n </div>\n </div>\n\n <!-- 3. 交互式组件：AT&T 长期 DRIP 复利与成本股息率（Yield on Cost）动态推演器 -->\n <div class=\"bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 rounded-2xl p-6 sm:p-8 text-white border border-slate-700 shadow-xl space-y-6 no-print\">\n <div class=\"flex flex-col md:flex-row md:items-center justify-between gap-3 pb-4 border-b border-slate-700/80\">\n <div>\n <div class=\"inline-flex items-center space-x-2 text-xs font-mono uppercase tracking-wider text-attblue-400 font-bold\">\n <span>TELECOM DIVIDEND COMPOUNDING SIMULATOR · AT&T 高息复利模拟器</span>\n </div>\n <h3 class=\"text-lg sm:text-xl font-bold text-white mt-1\">AT&T 长期 DRIP 股息再投资与成本股息率（Yield on Cost）动态推演器</h3>\n <p class=\"text-xs text-slate-400 mt-0.5\">基准参数：当前参考股价 $23.45 | 年化股息 $1.11/股（起始毛股息率 4.73%）| 支持不同海外美股税率测算</p>\n </div>\n <label class=\"inline-flex items-center space-x-2.5 px-3.5 py-2 rounded-xl bg-attblue-500/15 border border-attblue-400/30 text-xs font-semibold text-attblue-300 cursor-pointer shrink-0\">\n <input type=\"checkbox\" id=\"drip-toggle\" checked onchange=\"updateDividendSimulator()\" class=\"w-4 h-4 rounded accent-[#2563EB] cursor-pointer\">\n <span>开启股息自动再投资 (DRIP)</span>\n </label>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <!-- 左侧参数控制区 -->\n <div class=\"lg:col-span-5 space-y-4 text-xs\">\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">初始投入本金 (USD)</span>\n <span id=\"sim-principal-label\" class=\"font-mono font-bold text-white text-sm\">$30,000</span>\n </div>\n <input id=\"sim-principal\" type=\"range\" min=\"5000\" max=\"200000\" step=\"5000\" value=\"30000\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#2563EB] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">长期持有年限 (Years)</span>\n <span id=\"sim-years-label\" class=\"font-mono font-bold text-white text-sm\">10 年</span>\n </div>\n <input id=\"sim-years\" type=\"range\" min=\"1\" max=\"20\" step=\"1\" value=\"10\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#2563EB] cursor-pointer\">\n </div>\n\n <div>\n <div class=\"flex justify-between mb-1.5\">\n <span class=\"text-slate-300 font-medium\">年均股息增长率 (电信公用事业稳健中低速)</span>\n <span id=\"sim-growth-label\" class=\"font-mono font-bold text-emerald-400 text-sm\">2.0%</span>\n </div>\n <input id=\"sim-growth\" type=\"range\" min=\"0\" max=\"5\" step=\"0.5\" value=\"2.0\" oninput=\"updateDividendSimulator()\" class=\"w-full accent-[#10B981] cursor-pointer\">\n </div>\n\n <div class=\"pt-1\">\n <div class=\"text-slate-300 font-medium mb-2\">美股股息预扣税率（Withholding Tax）情景：</div>\n <div class=\"grid grid-cols-3 gap-2\" id=\"tax-btn-group\">\n <button type=\"button\" onclick=\"setTaxRate(0)\" data-tax=\"0\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-attblue-400 transition cursor-pointer\">\n 0% 免税账户<br><span class=\"text-[10px] text-slate-400\">IRA/RRSP等</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.10)\" data-tax=\"0.1\" class=\"tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-attblue-500 text-white border border-attblue-400 shadow transition cursor-pointer\">\n 10% 协定税率<br><span class=\"text-[10px] text-navy-900\">中美税收协定</span>\n </button>\n <button type=\"button\" onclick=\"setTaxRate(0.30)\" data-tax=\"0.3\" class=\"tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-attblue-400 transition cursor-pointer\">\n 30% 标准预扣<br><span class=\"text-[10px] text-slate-400\">新加坡/香港等</span>\n </button>\n </div>\n </div>\n </div>\n\n <!-- 右侧四大实时测算结果卡片 -->\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末预计总资产 (含税后分红)</div>\n <div id=\"sim-final-value\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-white mt-1.5\">$54,210</div>\n <div id=\"sim-total-return\" class=\"text-xs font-semibold text-emerald-400 mt-1.5\">累计总回报 +80.7%</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末年度税后股息现金流</div>\n <div id=\"sim-annual-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-attblue-400 mt-1.5\">$2,415</div>\n <div id=\"sim-monthly-div\" class=\"text-xs text-slate-400 mt-1.5\">折合每月被动现金流 ~$201</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">期末税后成本股息率 (Yield on Cost)</div>\n <div id=\"sim-yoc\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-teal-400 mt-1.5\">8.05%</div>\n <div class=\"text-xs text-slate-400 mt-1.5\">相对于初始投入本金的每年分红回报</div>\n </div>\n\n <div class=\"bg-navy-950/80 rounded-xl p-5 border border-slate-800\">\n <div class=\"text-xs text-slate-400\">持有期累计获配税后股息总额</div>\n <div id=\"sim-cum-div\" class=\"text-2xl sm:text-3xl font-mono font-extrabold text-emerald-400 mt-1.5\">$14,280</div>\n <div id=\"sim-shares-end\" class=\"text-xs text-slate-400 mt-1.5\">期末持仓股数：1,920.5 股 (起始 1,279.3 股)</div>\n </div>\n </div>\n </div>\n </div>\n\n <!-- 4. 华尔街多空核心分歧对比 -->\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">FCF 现金牛 + 高息防御</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>纯电信战略兑现与 FCF 超 165 亿：</strong>剥离媒体包袱后，主业现金流质量大幅跃升，完全保障每年 ~80 亿美元的稳健派息。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>5G 与千兆光纤双轮牢固护城河：</strong>Postpaid 手机用户流失率维持行业最低，AT&T Fiber 宽带 ARPU 与渗透率持续高速扩张。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>降息周期下稀缺的高股息资产：</strong>在宏观利率见顶或下行周期中，~4.75% 的高息稳健公用事业属性资产对长线资金具极强虹吸效应。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">资本密集 + 行业价格竞争</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>持续高额资本开支压力：</strong>无线频谱拍卖与光纤铺设需要长期庞大资本投入，限制了自由现金流爆发式增长的弹性。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>美国无线市场存量博弈激烈：</strong>三大运营商在无霜期互抢客户，价格战与以旧换新补贴可能阶段性侵蚀利润率。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>传统商业固网业务（Enterprise Wireline）萎缩：</strong>企业传统语音和专线业务受技术迭代冲击下滑，对整体收入增长形成小幅拖累。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 五、 投资决策与风险配置框架 (Investment Decision & Risk)\n ========================================================= -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-attblue-600 dark:text-attblue-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景估值推演与电信资产配置策略</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：高息防御核心底仓 · 9.0x–10.0x 逢回调积极加仓</span>\n </div>\n\n <!-- 1. 三情景估值推演卡片 (Bull / Base / Bear) -->\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <!-- 牛市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-emerald-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-emerald-500/15 text-emerald-600 dark:text-emerald-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-emerald-600 dark:text-emerald-400\">概率：25%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">11.0x–12.0x P/E ($27–$30)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>宏观降息周期全面开启，无风险收益率回落引发资金涌入高股息公用事业股；AT&T FCF 超预期突破 $180 亿美元，杠杆率降至 2.3x 以下。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-emerald-600 dark:text-emerald-400\">\n 含息潜在年化总回报：+18% 至 +24%\n </div>\n </div>\n\n <!-- 基准情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-attblue-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-attblue-500/15 text-attblue-700 dark:text-attblue-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-attblue-600 dark:text-attblue-400\">概率：55%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">9.5x–10.5x P/E ($23–$26)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>Mobility 与 Fiber 光纤业务稳步推进，自由现金流稳居 $165–$175 亿美元中枢，估值维持在 9.5x–10.5x 合理区间。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-attblue-600 dark:text-attblue-400\">\n 含息稳健年化总回报：+10% 至 +12%（高确定性收息）\n </div>\n </div>\n\n <!-- 熊市情景 -->\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">8.0x–8.5x P/E ($18–$20)</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>美国宏观经济陷入深度滞胀或长端美债收益率再次飙升压制所有红利股估值；无线行业价格战升级压低服务毛利率。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 含息潜在回撤：-10% 至 -15%（高股息率构筑强力底部）\n </div>\n </div>\n </div>\n\n <!-- 2. 四大核心风险矩阵 -->\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心潜在风险评估与跟踪边界</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 美国无线市场价格战与促销补贴</span>\n <span class=\"text-xs font-mono text-rose-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">运营商争夺用户激进补贴可能侵蚀营业利润率</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 美三大运营商在手机换代季常推出大额置换补贴，若营销战持续升级，将对短期的设备毛利与现金流转化造成阶段性摩擦。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 资本密集型开支与技术迭代压力</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">未来世代无线技术与光纤下沉的长期投资</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 电信行业属于重资产基础设施行业，若未来出现突发的频谱升级需求或光纤建设成本超出预算，将直接影响 FCF 释放进度。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">03 · 商业固网（Enterprise Wireline）加速萎缩</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">企业客户加速转向云服务削减传统固网专线</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 传统企业级固网业务的下滑趋势仍在继续，虽然占比在总营收中逐步稀释，但仍需关注其对整体营业利润的拖累效应。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">04 · 宏观利率与海外税收预扣政策</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">宏观利率波动对红利股估值及 10%–30% 股息预扣税</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 作为美股红利资产，海外投资者需留意当地税务居民身份对应的股息预扣税（中美协定通常为 10%），以及美债收益率变动对红利股估值的压制。\n </p>\n </div>\n </div>\n </div>\n\n <!-- 3. 机构级组合配置纪律横幅 -->\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-attblue-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合配置纪律与电信资产配置策略</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 高息防守与现金流压舱石</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 将 AT&T（T）作为资产配置中的高息防御底仓，利用其 ~4.75% 稳健股息与超 165 亿美元自由现金流对冲组合整体波动风险。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-attblue-400 mb-1\">2. 估值锚点与逢低加仓纪律</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 估值长期围绕 9.0x–10.0x Forward P/E 波动；若受宏观利率扰动导致股价回踩或股息率重返 5.0% 以上，则属于极佳的长线加仓窗口。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-emerald-400 mb-1\">3. 账户税务效率优化摆放</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 优先置于享受免税或税收协定优惠的账户（如美国 IRA 账户或享受 10% 中美协定税率的账户），最大化高额派息的 DRIP 复利威力。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 六、 季度基本面跟踪 KPI 交互式核查清单 (Checklist)\n ========================================================= -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-emerald-600 dark:text-emerald-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-attblue-500/15 text-attblue-700 dark:text-attblue-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition cursor-pointer\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选季度财报中已验证达标的经营指标（勾选状态自动本地保存），持续校验 AT&T 纯电信转型与现金流堡垒：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <!-- KPI 1 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. Postpaid 手机用户净增量与行业最低流失率 (Churn)</span>\n <span class=\"text-[11px] font-mono text-attblue-600 dark:text-attblue-400 font-semibold shrink-0\">无线基本盘锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查每季度 postpaid 手机净增用户数是否稳健，且手机流失率维持在行业领先的低位水平。\n </p>\n </div>\n </label>\n\n <!-- KPI 2 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. AT&T Fiber 千兆光纤家庭覆盖数与宽带 ARPU 提升</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">固网成长引擎</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪光纤通过家庭数（Passing Homes）扩张速度及光纤宽带 ARPU 是否保持稳步上升。\n </p>\n </div>\n </label>\n\n <!-- KPI 3 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. 全年自由现金流（FCF）指引兑现在 $165亿–$175亿 区间</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">现金流安全标尺</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 确认每季度经营现金流减去资本开支后的自由现金流是否如期达成管理层年度指引。\n </p>\n </div>\n </label>\n\n <!-- KPI 4 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 净债务杠杆率持续稳定在 ~2.5x 目标区间</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">资产负债表健康</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核查总债务压降进度及 EBITDA 盈利表现，确保净债务杠杆率保持在 2.5x 的健康安全红线内。\n </p>\n </div>\n </label>\n\n <!-- KPI 5 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. 无线服务收入（Wireless Service Revenue）保持 2%–4% 增长</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">核心收入质量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 评估剔除硬件销售后的纯无线服务收入增速，检验高价值套餐升级对 ARPU 的实质拉动作用。\n </p>\n </div>\n </label>\n\n <!-- KPI 6 -->\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#2563EB] focus:ring-attblue-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 资本开支（CapEx）维持在稳健的 ~$19亿 平台期</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">资本效率指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监督 CapEx 投资强度是否符合预期，避免大规模网络建设导致 FCF 出现不必要的阶段性波动。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- =========================================================\n 页脚免责声明\n ========================================================= -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>美国电话电报公司 AT&T Inc. (NYSE: T) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：2026Q3 财报及 2026 年 11 月市场一致预期 (FY26E)</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于 AT&T 公开财务报告（10-Q/10-K）、2026Q3 业绩说明会披露数据及全球电信行业调研资料整理生成，旨在提供结构化的产业分析与高息资产估值框架。报告中涉及的自由现金流预测、三情景目标价及 DRIP 股息复利模拟均基于特定假设条件推演，不构成任何证券买卖建议、税务规划意见或收益承诺。美股股息预扣税率因投资者国籍及账户属性存在差异，请在独立核实后审慎决策。\n </p>\n </footer>\n\n </div>\n </main>\n\n <!-- 交互逻辑与 Chart.js 可视化脚本 -->\n <script>\n // ==========================================\n // 1. 亮色 / 深色模式切换\n // ==========================================\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n // ==========================================\n // 2. 移动端抽屉菜单切换\n // ==========================================\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n // ==========================================\n // 3. 阅读进度条与左侧导航滚动联动高亮\n // ==========================================\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-attblue-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-attblue-400');\n }\n }\n });\n });\n\n // ==========================================\n // 4. 同行竞争格局矩阵筛选器\n // ==========================================\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-attblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-attblue-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n // ==========================================\n // 5. AT&T DRIP 复利与 Yield on Cost 动态推演器\n // ==========================================\n let currentTaxRate = 0.10; // 默认 10% 中美税收协定预扣税率\n\n function setTaxRate(rate) {\n currentTaxRate = rate;\n document.querySelectorAll('#tax-btn-group .tax-btn').forEach(btn => {\n const btnRate = parseFloat(btn.dataset.tax);\n if (Math.abs(btnRate - rate) < 0.001) {\n btn.className = 'tax-btn active px-2 py-2 rounded-lg text-[11px] font-bold bg-attblue-500 text-white border border-attblue-400 shadow transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-navy-900';\n } else {\n btn.className = 'tax-btn px-2 py-2 rounded-lg text-[11px] font-medium bg-navy-950/70 text-slate-300 border border-slate-700 hover:border-attblue-400 transition cursor-pointer';\n const subSpan = btn.querySelector('span');\n if (subSpan) subSpan.className = 'text-[10px] text-slate-400';\n }\n });\n updateDividendSimulator();\n }\n\n function updateDividendSimulator() {\n const principal = parseFloat(document.getElementById('sim-principal').value);\n const years = parseInt(document.getElementById('sim-years').value, 10);\n const growthPct = parseFloat(document.getElementById('sim-growth').value);\n const drip = document.getElementById('drip-toggle').checked;\n\n document.getElementById('sim-principal-label').textContent = '$' + principal.toLocaleString('en-US');\n document.getElementById('sim-years-label').textContent = years + ' 年';\n document.getElementById('sim-growth-label').textContent = growthPct.toFixed(1) + '%';\n\n const initPrice = 23.45;\n const initDps = 1.11;\n const g = growthPct / 100;\n\n const initialShares = principal / initPrice;\n let shares = initialShares;\n let sharePrice = initPrice;\n let dps = initDps;\n let cashPool = 0;\n let cumulativeNetDiv = 0;\n\n for (let y = 1; y <= years; y++) {\n const grossDiv = shares * dps;\n const netDiv = grossDiv * (1 - currentTaxRate);\n cumulativeNetDiv += netDiv;\n\n const nextPrice = sharePrice * (1 + g);\n if (drip) {\n const avgReinvestPrice = (sharePrice + nextPrice) / 2;\n shares += netDiv / avgReinvestPrice;\n } else {\n cashPool += netDiv;\n }\n sharePrice = nextPrice;\n if (y < years) {\n dps = dps * (1 + g);\n }\n }\n\n const endForwardDps = initDps * Math.pow(1 + g, years);\n const endAnnualNetDiv = shares * endForwardDps * (1 - currentTaxRate);\n const finalPortfolioVal = (shares * sharePrice) + cashPool;\n const totalReturnPct = ((finalPortfolioVal - principal) / principal) * 100;\n const yieldOnCost = (endAnnualNetDiv / principal) * 100;\n\n document.getElementById('sim-final-value').textContent = '$' + Math.round(finalPortfolioVal).toLocaleString('en-US');\n document.getElementById('sim-total-return').textContent = `累计总回报 +${totalReturnPct.toFixed(1)}% (${drip ? '含DRIP复利' : '现金分红留存'})`;\n document.getElementById('sim-annual-div').textContent = '$' + Math.round(endAnnualNetDiv).toLocaleString('en-US');\n document.getElementById('sim-monthly-div').textContent = `折合每月税后被动现金流 ~$${Math.round(endAnnualNetDiv / 12).toLocaleString('en-US')}`;\n document.getElementById('sim-yoc').textContent = yieldOnCost.toFixed(2) + '%';\n document.getElementById('sim-cum-div').textContent = '$' + Math.round(cumulativeNetDiv).toLocaleString('en-US');\n document.getElementById('sim-shares-end').textContent = `期末持仓股数：${shares.toFixed(1)} 股 (起始 ${initialShares.toFixed(1)} 股)`;\n }\n\n // ==========================================\n // 6. KPI 核查清单状态持久化与计数更新\n // ==========================================\n const KPI_STORAGE_KEY = 'att_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n // ==========================================\n // 7. Chart.js 数据可视化初始化与主题自适应\n // ==========================================\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let fcfTrendChartInstance = null;\n let currentBizMode = 'rev_fcf';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('attBizChart').getContext('2d');\n const colors = getChartColors();\n\n // 视图 A：2023–2026E 营业收入与自由现金流 ($B)\n const revFcfConfig = {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n label: '全年总营业收入 ($B)',\n data: [121.3, 122.4, 123.1, 122.8],\n backgroundColor: '#2563EB',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '自由现金流 FCF ($B)',\n data: [16.8, 17.1, 16.9, 17.2],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 2.5,\n pointRadius: 4,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 100,\n max: 140,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 10,\n max: 25,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n // 视图 B：2026Q3 用户与光纤指标\n const subSplitConfig = {\n type: 'bar',\n data: {\n labels: [\n 'Postpaid 手机用户流失率 (越低越优)',\n 'AT&T Fiber 千兆光纤家庭通过数 (百万)',\n '无线服务收入同比增速 (%)',\n '自由现金流占总营收比例 (%)'\n ],\n datasets: [\n {\n label: '2026Q3 核心电信指标',\n data: [0.79, 29.5, 3.2, 14.0],\n backgroundColor: [\n '#10B981',\n '#2563EB',\n '#60A5FA',\n '#06B6D4'\n ],\n borderRadius: 6,\n barThickness: 22\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `指标数值: ${ctx.parsed.x}`\n }\n }\n },\n scales: {\n x: {\n min: 0,\n max: 35,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 } }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'rev_fcf' ? revFcfConfig : subSplitConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnRev = document.getElementById('btn-chart-rev');\n const btnSplit = document.getElementById('btn-chart-split');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'rev_fcf') {\n btnRev.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-attblue-600 dark:text-attblue-400 shadow-sm transition cursor-pointer';\n btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2023–2026E 营业收入与自由现金流（FCF）演进';\n subEl.textContent = '剥离媒体后核心电信营收企稳于 ~$122B，资本开支回落驱动 FCF 强劲回升至 $17B 平台';\n } else {\n btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-attblue-600 dark:text-attblue-400 shadow-sm transition cursor-pointer';\n btnRev.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition cursor-pointer';\n titleEl.textContent = '2026Q3 核心电信运营指标与光纤覆盖拆解';\n subEl.textContent = '低流失率的 Postpaid 手机用户与近 3000 万光纤覆盖数构筑起坚实的主业壁垒';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '5G 频谱与无线网络质量',\n '千兆光纤（Fiber）固网资产',\n 'Postpaid 客户黏性与流失率',\n '自由现金流创造与派息安全',\n '资产负债表去杠杆进度'\n ],\n datasets: [\n {\n label: 'AT&T (T)',\n data: [9.3, 9.6, 9.5, 9.2, 8.8],\n borderColor: '#2563EB',\n backgroundColor: 'rgba(37, 99, 235, 0.24)',\n pointBackgroundColor: '#2563EB',\n borderWidth: 2.5\n },\n {\n label: 'Verizon (VZ)',\n data: [9.4, 8.9, 9.0, 9.3, 8.5],\n borderColor: '#10B981',\n backgroundColor: 'rgba(16, 185, 129, 0.14)',\n pointBackgroundColor: '#10B981',\n borderWidth: 2.0\n },\n {\n label: 'T-Mobile (TMUS)',\n data: [9.6, 7.5, 9.2, 8.2, 8.0],\n borderColor: '#06B6D4',\n backgroundColor: 'rgba(6, 182, 212, 0.12)',\n pointBackgroundColor: '#06B6D4',\n borderWidth: 1.8,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n 'AT&T (T · 纯电信高现金流防御)',\n 'Verizon (VZ · 高股息传统电信)',\n 'T-Mobile (TMUS · 无线成长先锋)',\n '沃达丰 (VOD · 欧洲跨国电信)'\n ],\n datasets: [\n {\n label: '营业利润率 Operating Margin (%)',\n data: [22.0, 23.5, 18.0, 15.0],\n backgroundColor: '#2563EB',\n borderRadius: 5,\n barThickness: 16\n },\n {\n label: '远期股息率 Dividend Yield (%)',\n data: [4.75, 6.10, 1.40, 5.50],\n backgroundColor: '#10B981',\n borderRadius: 5,\n barThickness: 16\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 30,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initFcfTrendChart() {\n const ctx = document.getElementById('fcfTrendChart').getContext('2d');\n const colors = getChartColors();\n\n if (fcfTrendChartInstance) fcfTrendChartInstance.destroy();\n fcfTrendChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['2023', '2024', '2025', '2026E'],\n datasets: [\n {\n type: 'bar',\n label: '自由现金流 FCF ($B)',\n data: [16.8, 17.1, 16.9, 17.2],\n backgroundColor: 'rgba(37, 99, 235, 0.85)',\n borderRadius: 5,\n barThickness: 28,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '资本开支 CapEx ($B)',\n data: [21.2, 19.8, 19.2, 18.9],\n borderColor: '#10B981',\n backgroundColor: '#10B981',\n borderWidth: 3,\n pointRadius: 5,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n min: 10,\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' },\n title: { display: true, text: '自由现金流 FCF ($B)', color: colors.text, font: { size: 11 } }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 10,\n max: 25,\n grid: { drawOnChartArea: false },\n ticks: { color: '#10B981', font: { size: 11, weight: '600' }, callback: v => '$' + v + 'B' },\n title: { display: true, text: '资本开支 CapEx ($B)', color: '#10B981', font: { size: 11 } }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initFcfTrendChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n updateDividendSimulator();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initFcfTrendChart();\n });\n </script>\n</body>\n</html>"};
